// Week 52 data-quality corrections: these records were carrying copied
// keyword arrays and duration labels that did not describe their itineraries.
// Keep the tour URLs and useful itinerary content unchanged; correct only the
// metadata that search engines and the booking cards consume.
const lucknowMetadataCorrections = {
  'lucknow-heritage-city-tour': {
    keywords: ['Lucknow heritage tour', 'Lucknow sightseeing tour', 'Bara Imambara tour', 'Lucknow city tour'],
    duration: 'Full day (approximately 9 hours)'
  },
  'lucknow-to-ayodhya-religious-tour': {
    keywords: ['Lucknow to Ayodhya religious tour', 'Ayodhya darshan from Lucknow', 'Lucknow Ayodhya cab tour'],
    duration: 'Full day (approximately 15 hours)'
  },
  'lucknow-to-prayagraj-religious-tour': {
    keywords: ['Lucknow to Prayagraj religious tour', 'Prayagraj Sangam tour from Lucknow', 'Lucknow Prayagraj cab tour'],
    duration: 'Full day (approximately 16.5 hours)'
  },
  'lucknow-nawabi-heritage-tour': {
    keywords: ['Lucknow Nawabi heritage tour', 'Lucknow food tour', 'Lucknow sightseeing by cab'],
    duration: 'Full day (approximately 8.5 hours)'
  }
};

for (const tours of Object.values(sightseeingTours)) {
  for (const tour of tours) {
    const correction = lucknowMetadataCorrections[tour.slug];
    if (correction) Object.assign(tour, correction);
  }
}

